            gridTop: gr.top,
            stickTop: sr.top, stickBottom: sr.bottom,
            planeTop: pr.top, planeBottom: pr.bottom,
          };
        }""")
        print("p=%.2f scrollY=%.0f ->" % (p_, y), json.dumps(r))
    b.close()

