    pg.wait_for_timeout(60)
    return pg.evaluate("""() => {
      const chEl = document.querySelector('.process-chapter');
      const chCs = getComputedStyle(chEl);
      const title = document.getElementById('process-title');
      const tr = title.getBoundingClientRect();
