        scPs: chCs.getPropertyValue('--sc-ps'),
        titleTop: tr.top, titleBottom: tr.bottom,
        gridTop: gr.top,
        stickTop: sr.top, stickBottom: sr.bottom,
        planeTop: pr.top, planeBottom: pr.bottom,
      };
    }""")

