        mid = (lo + hi) / 2
        r = read(pg, mid)
        if r["tx"] >= 0.999:
            hi = mid
        else:
            lo = mid
    r = read(pg, hi)
    print("landing scrollY ~=", hi)
    print(json.dumps(r, indent=2))
    b.close()

