from playwright.sync_api import sync_playwright
import json

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

def visible_rect(pg):
    return pg.evaluate("""() => {
      const el = document.querySelector('.tes-plane');
      const cs = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      const m = /^inset\\(([^)]+)\\)/.exec(cs.clipPath);
      if (!m) return {top:r.top,bottom:r.bottom,left:r.left,right:r.right, noclip:true};
      const raw = m[1].trim().split(/\\s+/).map(parseFloat);
      const [it, ir, ib, il] = raw.length===4?raw:[raw[0],raw[1]||0,raw[2]||raw[0],raw[3]||raw[1]||0];
      return {top:r.top+it, bottom:r.bottom-ib, left:r.left+il, right:r.right-ir};
    }""")

with sync_playwright() as p:
    b = p.chromium.launch()
    pg = b.new_page(viewport={"width": 1920, "height": 930})
    pg.goto(URL)
    pg.wait_for_timeout(500)
    ch = pg.evaluate("""() => {
      const el = document.querySelector('.process-chapter');
      const r = el.getBoundingClientRect();
      return {top: r.top + window.scrollY, height: el.offsetHeight, vh: window.innerHeight};
    }""")
    span = ch['height'] + ch['vh']
    bandH = pg.evaluate("() => parseFloat(getComputedStyle(document.getElementById('process')).getPropertyValue('--band-h'))||0")
    print("bandH:", bandH)
    for p_ in [0.30, 0.36, 0.40, 0.45, 0.50, 0.55, 0.60, 0.65, 0.70, 0.75, 0.80, 0.90, 1.0]:
        y = ch['top'] + p_ * span - ch['vh']
        pg.evaluate("(y) => window.scrollTo(0, Math.max(0,y))", y)
        pg.wait_for_timeout(80)
        vr = visible_rect(pg)
        title = pg.evaluate("() => { const r = document.getElementById('process-title').getBoundingClientRect(); return {top:r.top,bottom:r.bottom}; }")
        grid = pg.evaluate("() => document.querySelector('.process-grid').getBoundingClientRect().top")
        print("p=%.2f y=%.0f ark=%s title=%s gridTop=%.0f" % (p_, y, json.dumps(vr), json.dumps(title), grid))
    b.close()

