tool_use_result.originalFile:
from playwright.sync_api import sync_playwright
import json, sys

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
OUT = "tests/alunix-r8/runs/V3d/shots/r19"

def state(pg):
    return pg.evaluate("""() => {
      const plane = document.querySelector('.tes-plane');
      const title = document.getElementById('process-title');
      const grid = document.querySelector('.process-grid');
      const stick = document.querySelector('.process-stick');
      const sheet = document.querySelector('.process-sheet');
      const pr = plane.getBoundingClientRect();
      const sr = stick.getBoundingClientRect();
      const shr = sheet.getBoundingClientRect();
      return {
        frozen: plane.hasAttribute('data-frozen'),
        gone: plane.hasAttribute('data-gone'),
        opacity: getComputedStyle(plane).opacity,
        planeRect: {top: pr.top, left: pr.left, width: pr.width, height: pr.height},
        titleBottom: title.getBoundingClientRect().bottom,
        gridTop: grid.getBoundingClientRect().top,
        stickRect: {top: sr.top, left: sr.left, width: sr.width, height: sr.height},
        sheetRect: {top: shr.top, left: shr.left, width: shr.width, height: shr.height},
      };
    }""")

def run(w, h):
    with sync_playwright() as p:
        b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(URL)
        pg.wait_for_timeout(400)
        ch = pg.evaluate("""() => {
          const el = document.querySelector('.process-chapter');
          const r = el.getBoundingClientRect();
          return {top: r.top + window.scrollY, height: el.offsetHeight, vh: window.innerHeight};
        }""")
        total = ch['height'] + ch['vh']
        start = ch['top'] - ch['vh']
        end = ch['top'] + ch['height'] + 300
        y = start
        step = 20
        prev_frozen = False
        prev_gone = False
        shots = 0
        while y <= end:
            pg.evaluate("(y) => window.scrollTo(0, Math.max(0,y))", y)
            pg.wait_for_timeout(30)
            st = state(pg)
            if st['frozen'] != prev_frozen:
                print("%d: FROZEN -> %s at y=%.0f  %s" % (w, st['frozen'], y, json.dumps(st)))
                pg.screenshot(path="%s/cont-%d-frozen-change.png" % (OUT, w))
                prev_frozen = st['frozen']
            if st['gone'] != prev_gone:
                print("%d: GONE -> %s at y=%.0f  %s" % (w, st['gone'], y, json.dumps(st)))
                pg.screenshot(path="%s/cont-%d-gone-change.png" % (OUT, w))
                prev_gone = st['gone']
            y += step
        b.close()

for w, h in [(1920, 930), (1440, 900), (768, 1024), (390, 844)]:
    run(w, h)
print("done")

