          const fz = document.querySelector('.process-chapter');
          const fzT = parseFloat(getComputedStyle(fz).getPropertyValue('--fz-t'))||0;
          const fzH = parseFloat(getComputedStyle(fz).getPropertyValue('--fz-h'))||0;
          return {
            titleBottom: title.getBoundingClientRect().bottom,
            upTop: up.getBoundingClientRect().top,
            upBottom: up.getBoundingClientRect().bottom,
            fzTop: fzT, fzBottom: fzT+fzH,
          };
        }""")
        print(y, r)
    b.close()

