from playwright.sync_api import sync_playwright
import json

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    pg = b.new_page(viewport={"width": 1920, "height": 930})
    pg.goto(URL)
    pg.wait_for_timeout(400)
    pg.evaluate("window.scrollTo(0, 7700)")
    pg.wait_for_timeout(150)
    r = pg.evaluate("""() => {
      const plane = document.querySelector('.tes-plane');
      const pr = plane.getBoundingClientRect();
      const titles = Array.from(document.querySelectorAll('.process-step-title'));
      const hits = titles.map(t => {
        const r = t.getBoundingClientRect();
        return {text: t.textContent, top: r.top, bottom: r.bottom, left: r.left, right: r.right, visible: r.width>0 && r.height>0};
      });
      return {
        frozen: plane.hasAttribute('data-frozen'), gone: plane.hasAttribute('data-gone'),
        planeRect: {top: pr.top, left: pr.left, width: pr.width, height: pr.height},
        titles: hits,
      };
    }""")
    print(json.dumps(r, indent=2))
    pg.screenshot(path="tests/alunix-r8/runs/V3d/shots/r19/debug-overlap-1920.png")
    b.close()

