from playwright.sync_api import sync_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

with sync_playwright() as p:
    b = p.chromium.launch()
    pg = b.new_page(viewport={"width": 1920, "height": 930})
    pg.goto(URL + "?preview=process-05")
    for t in [500, 1000, 2000, 4000, 8000]:
        pg.wait_for_timeout(t if t == 500 else t - [500,1000,2000,4000,8000][[500,1000,2000,4000,8000].index(t)-1] if t != 500 else t)
    pg.wait_for_timeout(500)
    pg.screenshot(path="tests/alunix-r8/runs/V3d/shots/r19/process05-wait-a.png")
    pg.wait_for_timeout(5000)
    pg.screenshot(path="tests/alunix-r8/runs/V3d/shots/r19/process05-wait-b.png")
    r = pg.evaluate("""() => {
      const frame = document.querySelector('.process-sheet iframe, .process-sheet img');
      const embeds = Array.from(document.querySelectorAll('.process-sheet foreignObject, .process-sheet image'));
      return {frameFound: !!frame, embedCount: embeds.length,
        embeds: embeds.map(e => ({tag: e.tagName, href: e.getAttribute('href')||e.getAttribute('xlink:href')||'', display: getComputedStyle(e).display}))};
    }""")
    print(r)
    b.close()

