from playwright.sync_api import sync_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
OUT = "tests/alunix-r8/runs/V3d/shots/r19"

def goto_p(pg, p):
    pg.evaluate("""(p) => {
      const el = document.querySelector('.process-chapter');
      const rect = el.getBoundingClientRect();
      const top = rect.top + window.scrollY;
      const height = el.offsetHeight, vh = window.innerHeight;
      window.scrollTo(0, Math.round(top + p * (height + vh) - vh));
    }""", p)

with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    for w, h in [(1920, 930), (1440, 900), (768, 1024), (390, 844)]:
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(URL)
        pg.wait_for_timeout(400)
        goto_p(pg, 0.20)
        pg.wait_for_timeout(200)
        pg.mouse.move(w // 2, h // 2)
        i = 0
        for _ in range(24):
            pg.mouse.wheel(0, 25)
            pg.wait_for_timeout(35)
            pg.screenshot(path="%s/final-wheel-down-%d-%02d.png" % (OUT, w, i))
            i += 1
        pg.wait_for_timeout(150)
        j = 0
        for _ in range(24):
            pg.mouse.wheel(0, -25)
            pg.wait_for_timeout(35)
            pg.screenshot(path="%s/final-wheel-up-%d-%02d.png" % (OUT, w, j))
            j += 1
        pg.close()
    b.close()
print("done")

